import sys
import re
from telnetlib import Telnet
import paramiko
from contextlib import contextmanager

AASHELL_PROMPT = 'AaShell>'
ENB_USERNAME = 'toor4nsn'
ENB_PASSWORD = 'oZPS0POrRieRtu'
GET_AASHELL_CELL_MAPPING = 'getCellMapping @RROMexe'
LNCEL_KEY = 'lcr'


def _bytes_conv(string):
    """
    Method for changing strings to bytes under Python3 (if needed).
    Will return string as is under Python2.
    """
    if sys.version_info > (3, 0):
        try:
            string = bytes(string, 'utf-8')
        except TypeError:
            pass
    return string


def _string_conv(bytes):
    """
    Method for changing bytes to string under Python3 (if needed).
    Will return string as is under Python2.
    """
    if sys.version_info > (3, 0):
        try:
            return bytes.decode('utf-8')
        except:
            pass
    return bytes


@contextmanager
def _ssh(host, port):
    client = paramiko.SSHClient()
    client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    client.connect(host, username=ENB_USERNAME, password=ENB_PASSWORD)
    client.aashell_port = port
    yield client
    client.close()


def _get_ssh_output(connection, command):
    full_command = 'echo \"{}\" | nc 127.0.0.1 {}'.format(command, connection.aashell_port)
    stdin, stdout, stderr = connection.exec_command(_bytes_conv(full_command))
    output = _string_conv(stdout.read())
    output = output.replace(AASHELL_PROMPT, '')
    return output


@contextmanager
def _telnet(host, port):
    telnet = Telnet()
    telnet.open(host, port)
    yield telnet
    telnet.close()


def _get_telnet_output(connection, command):
    connection.read_until(_bytes_conv(AASHELL_PROMPT))
    connection.write(_bytes_conv(command + '\n'))
    command_output = _string_conv(connection.read_until(_bytes_conv(AASHELL_PROMPT)))
    output_without_shell_prompt = command_output[:len(command_output) - len(AASHELL_PROMPT)]
    return output_without_shell_prompt


aashell_mediums = {'telnet': {'manager': _telnet, 'reader': _get_ssh_output},
                   'ssh': {'manager': _ssh, 'reader': _get_ssh_output}}


def execute_aashell_command(command, enb_ip='192.168.255.1', aashell_port='15007', medium='ssh'):
    """
    Executes aashell command and returns output
    :param command: command to execute
    :param enb_ip:
    :param aashell_port:
    :medium medium for aaShell connection
    :return: command output as string
    """
    assert medium in aashell_mediums, 'Available mediums: {}'.format(list(aashell_mediums.keys()))
    conn_manager = aashell_mediums[medium]['manager']
    with conn_manager(enb_ip, aashell_port) as connection:
        reader = aashell_mediums[medium]['reader']
        output = reader(connection, command)
    return output


def get_cell_mapping(aashell_port='15007'):
    """
    Updates cell mapping and returns cell mapping from AaShell in dict format
    :return: cell mapping as dict
    """
    raw_cell_mapping = execute_aashell_command(GET_AASHELL_CELL_MAPPING, aashell_port=aashell_port)
    cell_mapping_dict = _make_mapping_dict(raw_cell_mapping)

    return cell_mapping_dict


def _get_mapping_data_lines(raw_mapping_data):
    lines = raw_mapping_data.strip().splitlines()
    return [line.split() for line in lines]


def _create_mapping_dicts_list(mapping_keys, cell_values):
    return [dict(list(zip(mapping_keys, cell_values_per_cell))) for cell_values_per_cell in cell_values]


def _make_mapping_dict(raw_mapping_data):
    """ Takes raw mapping output from aashell
    'lcr lnCel pci eutraCelId chBw noRx CaPoolId ULCoMP L1PoolType              L2PoolType                UEC'\
    '     CELLC   MACCELL MACULTTI   MACDLTTI   TUPU    DL-PHY  UL-PHY\n11  1     11  267        20M  0    1'\
    '        -      FSMr3_FDD_L1_Basic      FSMr3_FDD_L2_12Core_Basic 0x120d  0x120d  0x1273'\
    '  0x00000000 0x00000000 0x1272  0x1244  0x1241\n12  2     12  268        20M  0    2        -'\
    '      FSMr3_FDD_L1_Basic      FSMr3_FDD_L2_12Core_Basic 0x120d  0x120d  0x1273  0x00000000 0x00000000'\
    ' 0x1272  0x1264  0x1261\n13  3     13  269        20M  0    3        -      FSMr3_FDD_L1_Basic'\
    '      FSMr3_FDD_L2_12Core_Basic 0x120d  0x120d  0x1273  0x00000000 0x00000000 0x1272  0x1284  0x1281\n'

    and returns mapping dict

    {'11': {'TUPU': '0x1272', 'UL-PHY': '0x1241', 'MACCELL': '0x1273', 'lcr': '11',
                                     'L1PoolType': 'FSMr3_FDD_L1_Basic', 'MACDLTTI': '0x00000000', 'noRx': '0',
                                     'L2PoolType': 'FSMr3_FDD_L2_12Core_Basic', 'UEC': '0x120d', 'chBw': '20M',
                                     'CaPoolId': '1', 'eutraCelId': '267', 'pci': '11', 'DL-PHY': '0x1244',
                                     'CELLC': '0x120d', 'MACULTTI': '0x00000000', 'ULCoMP': '-', 'lnCel': '1'},
                              '13': {'TUPU': '0x1272', 'UL-PHY': '0x1281', 'MACCELL': '0x1273', 'lcr': '13',
                                     'L1PoolType': 'FSMr3_FDD_L1_Basic', 'MACDLTTI': '0x00000000', 'noRx': '0',
                                     'L2PoolType': 'FSMr3_FDD_L2_12Core_Basic', 'UEC': '0x120d', 'chBw': '20M',
                                     'CaPoolId': '3', 'eutraCelId': '269', 'pci': '13', 'DL-PHY': '0x1284',
                                     'CELLC': '0x120d', 'MACULTTI': '0x00000000', 'ULCoMP': '-', 'lnCel': '3'},
                              '12': {'TUPU': '0x1272', 'UL-PHY': '0x1261', 'MACCELL': '0x1273', 'lcr': '12',
                                     'L1PoolType': 'FSMr3_FDD_L1_Basic', 'MACDLTTI': '0x00000000', 'noRx': '0',
                                     'L2PoolType': 'FSMr3_FDD_L2_12Core_Basic', 'UEC': '0x120d', 'chBw': '20M',
                                     'CaPoolId': '2', 'eutraCelId': '268', 'pci': '12', 'DL-PHY': '0x1264',
                                     'CELLC': '0x120d', 'MACULTTI': '0x00000000', 'ULCoMP': '-', 'lnCel': '2'}}
    """
    mapping_data_lines = _get_mapping_data_lines(raw_mapping_data)
    mapping_keys = mapping_data_lines[0]
    cell_values = mapping_data_lines[1:]
    mapping_dicts_list = _create_mapping_dicts_list(mapping_keys, cell_values)
    return {mapping_dict[LNCEL_KEY]: mapping_dict for mapping_dict in mapping_dicts_list}


class RaDParamChangeFailed(Exception):
    """

    """
    pass


class RaDParamImproperFormat(Exception):
    """

    """
    pass


CHANGE_COMMAND = 'rad -m{change_type}w {param} {value}'


def _is_in_proper_format(param):
    return re.match(r'0x[a-fA-F0-9]+', param)


def change_rad_param(param, value, is_permanent=True):
    """
    Changes RaD parameter online through AaShell permanently
    :param param: parameter to change in hex format (0x###)
    :param value: value of parameter
    :param is_permanent: is parameter change done permanently
    """
    if not _is_in_proper_format(param):
        raise RaDParamImproperFormat('Given parameter not in proper hex format')

    change_type = 'p' if is_permanent else 'o'
    cmd = CHANGE_COMMAND.format(change_type=change_type, param=param, value=value)
    output = execute_aashell_command(cmd)

    print(("*INFO*", output))
    if 'written succesfully' not in output:
        raise RaDParamChangeFailed("RaD parameter change was unsuccessful: %s" % repr(output))

